// Diagnostic only: observe the actual game's Web Audio output without resuming it.
window.pursuitAudioProbe = [];
const originalConnect = AudioNode.prototype.connect;
AudioNode.prototype.connect = function (...args) {
  const probe = window.pursuitAudioProbe.find(p => p.context === this.context);
  if (probe && args[0] === this.context.destination && this !== probe.analyser) {
    originalConnect.call(this, probe.analyser);
    probe.connections += 1;
  }
  return Reflect.apply(originalConnect, this, args);
};
window.AudioContext = new Proxy(window.AudioContext, {
  construct(target, args, constructor) {
    const context = Reflect.construct(target, args, constructor);
    const analyser = context.createAnalyser();
    analyser.fftSize = 2048;
    const probe = {context, analyser, samples: new Float32Array(2048), peak: 0,
      nonzeroWindows: 0, connections: 0};
    window.pursuitAudioProbe.push(probe);
    return context;
  },
});
setInterval(() => {
  for (const probe of window.pursuitAudioProbe) {
    probe.analyser.getFloatTimeDomainData(probe.samples);
    let peak = 0;
    for (const sample of probe.samples) peak = Math.max(peak, Math.abs(sample));
    probe.peak = Math.max(probe.peak, peak);
    if (peak > 0) probe.nonzeroWindows += 1;
  }
}, 20);
